//! Port of `tests/test11.cpp` from the hopscotch-map test suite.
//!
//! The original, verbatim:
//!
//! ```cpp
//! int main(int argc, char* argv[]) {
//!     int count = 11;
//!     if (argc > 1 && std::string(argv[1]) == "--a") {
//!         count = std::stoi(argv[2]);
//!     }
//!
//!     tsl::hopscotch_map<int, int> map;
//!     for (int i = 0; i < count; i++) {
//!         map.insert({i, i * 9});
//!     }
//!
//!     std::cout << map.load_factor() << " ";
//!     map.max_load_factor(0.5);
//!     map.rehash(0);
//!     std::cout << map.load_factor() << std::endl;
//!
//!     return 0;
//! }
//! ```
//!
//! What the program actually measures is the container's bucket-count policy.
//! `map` starts with no buckets; inserting element number `size + 1` first checks
//! `size >= trunc(bucket_count * max_load_factor)` and, if so, doubles the bucket
//! count (from zero it jumps straight to two). With the default `max_load_factor`
//! of `0.9f` that gives thresholds of 0, 1, 3, 7, 14, 28, 57, 115, 230, ... so the
//! first printed load factor lands anywhere in roughly `[0.45, 0.9]`. Dropping
//! `max_load_factor` to 0.5 and calling `rehash(0)` then resizes to
//! `ceil(size / 0.5)` rounded up to a power of two, which is why the second value
//! is never above 0.5.
//!
//! See [`tsl`] for the container and [`cxx`] for the C++ runtime behaviour
//! (`printf("%g")` formatting, `std::stoi`, and the uncaught-exception abort path)
//! that the byte-for-byte output depends on.

mod cxx;
mod tsl;

use std::io::Write;

use cxx::{argv, ostream, stoi, terminate};
use tsl::HopscotchMap;

/// The flag that switches the element count away from its default.
const COUNT_FLAG: &[u8] = b"--a";

/// The default element count, as in the C++ source.
const DEFAULT_COUNT: i32 = 11;

/// `map.max_load_factor(0.5)`.
const REDUCED_MAX_LOAD_FACTOR: f32 = 0.5;

fn main() {
    let count = parse_count(&argv::argv_bytes());

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    // `std::cout` records a failed write in its state flags and carries on, and
    // this `main` never inspects those flags, so a write error is simply ignored
    // and the process still exits 0. Propagating it here would instead panic.
    let _ = run(count, &mut out);
    let _ = out.flush();
}

/// Resolve the element count from the command line.
///
/// Any failure here is a C++ exception escaping `main`, which does not return: it
/// prints libstdc++'s terminate message and aborts.
fn parse_count(argv: &[Vec<u8>]) -> i32 {
    if argv.len() <= 1 || argv[1].as_slice() != COUNT_FLAG {
        return DEFAULT_COUNT;
    }

    match argv.get(2) {
        Some(text) => match stoi::stoi(text) {
            Ok(count) => count,
            Err(error) => {
                terminate::terminate_after_uncaught_exception(error.exception_type(), error.what())
            }
        },
        // With only "--a" on the command line, `argv[2]` is the NULL that
        // terminates the argv array, and `std::string(nullptr)` throws.
        None => terminate::terminate_after_uncaught_exception(
            "std::logic_error",
            "basic_string::_S_construct null not valid",
        ),
    }
}

/// Write the program's single line of output: the load factor after `count`
/// insertions, then the load factor after tightening `max_load_factor` to 0.5 and
/// rehashing.
///
/// The two values are written as they are produced, in the same order as the C++
/// original, rather than assembled first.
fn run(count: i32, out: &mut impl Write) -> std::io::Result<()> {
    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    for i in 0..count {
        // `i * 9` overflows for counts past ~2.4e8, which is undefined in C++ but
        // wraps in practice on every real compiler.
        map.insert(i, i.wrapping_mul(9));
    }

    write!(out, "{} ", ostream::to_string_f32(map.load_factor()))?;

    map.set_max_load_factor(REDUCED_MAX_LOAD_FACTOR);
    map.rehash(0);

    writeln!(out, "{}", ostream::to_string_f32(map.load_factor()))
}

